import xml.etree.ElementTree as ET
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
f='xl/worksheets/sheet2.xml'
root=ET.parse(f).getroot()
for row in root.findall('m:sheetData/m:row', ns):
    r=int(row.get('r'))
    cells=[]
    for c in row.findall('m:c', ns):
        ref=c.get('r'); t=c.get('t'); s=c.get('s')
        v=c.find('m:v', ns); isv=c.find('m:is/m:t', ns); f=c.find('m:f', ns)
        vt=v.text if v is not None else None
        if isv is not None: val='STR:'+repr(isv.text)
        elif f is not None: val='FORMULA:'+repr(f.text)+' v='+repr(vt)
        elif vt is not None: val='V:'+vt
        else: val='-'
        cells.append(f'{ref}(s{s},t{t})={val}')
    if cells:
        print('row', r, ' :: ', ' '.join(cells))
